local _, namespace = ...
namespace.releaseNotesByLocale = {["deDE"]={["sections"]={{["items"]={"Ein Fenster mit Questdetails zum Lesen verfügbarer Questtexte wurde hinzugefügt.","Die optionale Entwicklerdiagnose und die Zuverlässigkeit der Kommunikation wurden verbessert. Deine Einstellung zum Teilen von Diagnosedaten wird berücksichtigt."},["title"]="Verbesserungen"}},["version"]="7.0.2",["welcome"]="Einige Verbesserungen an Questinformationen und optionalen Diagnosedaten."},["esES"]={["sections"]={{["items"]={"Se ha añadido una ventana de Detalles de la misión para leer los textos de misión disponibles.","Se han mejorado los diagnósticos opcionales para el desarrollador y la fiabilidad de las comunicaciones. Se respeta tu ajuste para compartir datos de diagnóstico."},["title"]="Mejoras"}},["version"]="7.0.2",["welcome"]="Algunas mejoras en la información de las misiones y los diagnósticos opcionales."},["esMX"]={["sections"]={{["items"]={"Se agregó una ventana de Detalles de la misión para leer los textos de misión disponibles.","Se mejoraron los diagnósticos opcionales para el desarrollador y la confiabilidad de las comunicaciones. Se respeta tu configuración para compartir datos de diagnóstico."},["title"]="Mejoras"}},["version"]="7.0.2",["welcome"]="Algunas mejoras en la información de las misiones y los diagnósticos opcionales."},["frFR"]={["sections"]={{["items"]={"Ajout d’une fenêtre Détails de la quête pour lire les textes de quête disponibles.","Amélioration des diagnostics facultatifs destinés au développeur et de la fiabilité des communications. Votre réglage de partage des données de diagnostic est respecté."},["title"]="Améliorations"}},["version"]="7.0.2",["welcome"]="Quelques améliorations aux informations de quête et aux diagnostics facultatifs."},["itIT"]={["sections"]={{["items"]={"Aggiunta una finestra Dettagli della missione per leggere i testi delle missioni disponibili.","Migliorate la diagnostica facoltativa per lo sviluppatore e l’affidabilità delle comunicazioni. La tua impostazione di condivisione dei dati diagnostici viene rispettata."},["title"]="Miglioramenti"}},["version"]="7.0.2",["welcome"]="Alcuni miglioramenti alle informazioni sulle missioni e alla diagnostica facoltativa."},["koKR"]={["sections"]={{["items"]={"제공되는 퀘스트 텍스트를 읽을 수 있는 퀘스트 정보 창을 추가했습니다.","선택적 개발자 진단 기능과 통신 안정성을 개선했습니다. 진단 데이터 공유 설정이 적용됩니다."},["title"]="개선 사항"}},["version"]="7.0.2",["welcome"]="퀘스트 정보와 선택적 진단 기능을 개선했습니다."},["ptBR"]={["sections"]={{["items"]={"Adicionada uma janela de Detalhes da missão para ler os textos de missão disponíveis.","Melhorados os diagnósticos opcionais para o desenvolvedor e a confiabilidade da comunicação. Sua configuração de compartilhamento de dados de diagnóstico é respeitada."},["title"]="Melhorias"}},["version"]="7.0.2",["welcome"]="Algumas melhorias nas informações de missões e nos diagnósticos opcionais."},["ruRU"]={["sections"]={{["items"]={"Добавлено окно «Описание задания» для чтения доступного текста задания.","Улучшены необязательная диагностика для разработчика и надёжность обмена данными. Ваша настройка отправки диагностических данных учитывается."},["title"]="Улучшения"}},["version"]="7.0.2",["welcome"]="Небольшие улучшения информации о заданиях и необязательной диагностики."},["zhCN"]={["sections"]={{["items"]={"新增任务详情窗口，可阅读当前可获取的任务文本。","改进了可选的开发者诊断功能和通信可靠性，并遵循你的诊断数据共享设置。"},["title"]="改进内容"}},["version"]="7.0.2",["welcome"]="对任务信息和可选诊断功能进行了一些改进。"},["zhTW"]={["sections"]={{["items"]={"新增任務詳情視窗，可閱讀目前可取得的任務文字。","改善了可選的開發者診斷功能與通訊可靠性，並遵循你的診斷資料分享設定。"},["title"]="改善項目"}},["version"]="7.0.2",["welcome"]="針對任務資訊與可選診斷功能進行了一些改進。"}}
